	return sprintf(
		'<svg class="%1$s" width="%2$d" height="%2$d" viewBox="0 0 32 32" aria-hidden="true" focusable="false"><rect width="32" height="32" rx="8" fill="#0068FF"/><g transform="translate(4 4.6) scale(1)" fill="#fff"><path d="%3$s"/></g></svg>',
