/**
 * A brand mark (filled, in the brand's own colour), for share links where the
 * outline set has no equivalent. Paths: Simple Icons (CC0).
 *
 * @param string $name facebook|linkedin.
 * @param int    $size Width and height in px.
 */
function starter_flexible_brand_icon( string $name, int $size = 18 ): string {
	$brands = array(
		'facebook' => array( '#0866FF', 'M9.101 23.691v-7.98H6.627v-3.667h2.474v-1.58c0-4.085 1.848-5.978 5.858-5.978.401 0 .955.042 1.468.103a8.68 8.68 0 0 1 1.141.195v3.325a8.623 8.623 0 0 0-.653-.036 26.805 26.805 0 0 0-.733-.009c-.707 0-1.259.096-1.675.309a1.686 1.686 0 0 0-.679.622c-.258.42-.374.995-.374 1.752v1.297h3.919l-.386 2.103-.287 1.564h-3.246v8.245C19.396 23.238 24 18.179 24 12.044c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.628 3.874 10.35 9.101 11.647Z' ),
		'linkedin' => array( '#0A66C2', 'M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.85 1.637-1.71 3.37-1.71 3.601 0 4.267 2.37 4.267 4.892v4.71zM5.337 7.433a2.062 2.062 0 0 1-2.063-2.065 2.064 2.064 0 1 1 2.063 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z' ),
	);
	if ( ! isset( $brands[ $name ] ) ) {
		return starter_flexible_icon( 'share', $size );
	}
	return sprintf(
		'<svg class="brand-icon brand-icon--%1$s" width="%2$d" height="%2$d" viewBox="0 0 24 24" fill="%3$s" style="flex:none" aria-hidden="true" focusable="false"><path d="%4$s"/></svg>',
		esc_attr( $name ),
		$size,
		esc_attr( $brands[ $name ][0] ),
		esc_attr( $brands[ $name ][1] )
	);
}
